Clase Cancion
    Privado Definir duracion Como Entero;

    Metodo Constructor(unaDuracion Como Entero)
        Este.duracion <- unaDuracion;
    FinMetodo

    Publico Metodo Duracion() Como Entero
        Retornar Este.duracion;
    FinMetodo
FinClase

Clase Reproductor
    Privado Definir cancion Como Cancion;

    Metodo Constructor(unaDuracion Como Entero)
        Este.cancion <- Nuevo Cancion(unaDuracion);
    FinMetodo

    Publico Metodo Restante(transcurrido Como Entero) Como Entero
        Retornar Este.cancion.Duracion() - transcurrido;
    FinMetodo
FinClase

Proceso CalcularRestante
    Definir duracion Como Entero;
    Definir transcurrido Como Entero;
    Definir reproductor Como Reproductor;
    Leer duracion;
    Leer transcurrido;
    reproductor <- Nuevo Reproductor(duracion);
    Escribir reproductor.Restante(transcurrido);
FinProceso
